export type HubFrame = ChallengeFrame | ReadyFrame | RequestFrame | CloseFrame

/**
 * The exact bytes a host signs during the handshake. Binding the hub origin,
 * host id, nonce and time stops a captured signature from being replayed on
 * another hub, for another host, or later.
 */
export function hostAuthMessage(origin: string, hostId: string, nonce: string, issuedAt: number): string {
  return ['remora-host-auth/v1', origin, hostId, nonce, String(issuedAt)].join('\n')
}

const HOST_FRAME_TYPES = new Set(['hello', 'auth', 'response', 'event'])
const HUB_FRAME_TYPES = new Set(['challenge', 'ready', 'request', 'close'])

function parseObject(text: string): Record<string, unknown> {
  let value: unknown
  try {
    value = JSON.parse(text)
  } catch {
    throw new ProtocolError('invalid_request', 'frame is not JSON')
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new ProtocolError('invalid_request', 'frame is not an object')
  }
  return value as Record<string, unknown>
}

function requireString(frame: Record<string, unknown>, key: string): void {
  if (typeof frame[key] !== 'string' || frame[key] === '') throw new ProtocolError('invalid_request', `frame.${key} must be a non-empty string`)
}

/** Parse a frame sent by a host. Only shape is checked here; meaning is checked by the receiver. */
export function parseHostFrame(text: string): HostFrame {
  const frame = parseObject(text)
  if (typeof frame.t !== 'string' || !HOST_FRAME_TYPES.has(frame.t)) throw new ProtocolError('invalid_request', 'unknown host frame type')
  if (frame.t === 'hello') {
    requireString(frame, 'hostId')
    if (typeof frame.protocol !== 'number') throw new ProtocolError('invalid_request', 'frame.protocol must be a number')
    if (!Array.isArray(frame.operations)) throw new ProtocolError('invalid_request', 'frame.operations must be an array')
  }
  if (frame.t === 'auth') { requireString(frame, 'nonce'); requireString(frame, 'signature') }
  if (frame.t === 'response') {
    requireString(frame, 'id')
    if (typeof frame.ok !== 'boolean') throw new ProtocolError('invalid_request', 'frame.ok must be a boolean')
  }
  if (frame.t === 'event' && !Array.isArray(frame.events)) throw new ProtocolError('invalid_request', 'frame.events must be an array')
  return frame as unknown as HostFrame
}

/** Parse a frame sent by the hub. */
export function parseHubFrame(text: string): HubFrame {
  const frame = parseObject(text)
  if (typeof frame.t !== 'string' || !HUB_FRAME_TYPES.has(frame.t)) throw new ProtocolError('invalid_request', 'unknown hub frame type')
  if (frame.t === 'challenge') {
    requireString(frame, 'nonce'); requireString(frame, 'origin')
    if (typeof frame.issuedAt !== 'number') throw new ProtocolError('invalid_request', 'frame.issuedAt must be a number')
  }
  if (frame.t === 'request') {
    requireString(frame, 'id'); requireString(frame, 'op')
    if (typeof frame.deadline !== 'number') throw new ProtocolError('invalid_request', 'frame.deadline must be a number')
  }
  return frame as unknown as HubFrame
}
